//! Fill & Sign: AcroForm field widgets, text and checkbox filling.
//!
//! All PDF semantics live in `pdfxi_forms::document_form`: this module reads the
//! catalog `/AcroForm` into an [`AcroFormModel`], draws one widget per
//! [`FormWidget`] at its real `/Rect`, and commits a text or checkbox change as
//! one `DocumentSession::edit`, so undo, redo, save and the dirty marker work
//! exactly like every other edit. Appearances are regenerated by the library;
//! the shell only reloads the canvas afterwards.
//!
//! The shell never parses a field dictionary, never writes `/V` itself and never
//! executes JavaScript or XFA. A document that carries either is reported in the
//! panel banner and its AcroForm fields stay fillable.

use pdfxi_forms::{
    AcroFormModel, FieldValue, FormFieldKind, FormRect, read_acroform, set_checkbox, set_text,
};
use pdfxi_security::Permission;

use crate::canvas::{CanvasLayout, CanvasRect};
use crate::design::Palette;
use crate::ui::{AppCommand, Capability, PdfxiApp};

/// Shell state for the Fill & Sign tool.
#[derive(Default)]
pub(crate) struct FormsUiState {
    /// Cached model for the active tab, keyed by [`Self::revision`].
    pub(crate) model: Option<AcroFormModel>,
    /// Session revision the cached model was read at.
    pub(crate) revision: Option<usize>,
    /// Tab the cached model belongs to.
    pub(crate) tab: Option<crate::TabId>,
    /// Whether the Fill & Sign panel window is open.
    pub(crate) panel_open: bool,
    /// Blocking read error or a notice about unexecuted XFA/JavaScript.
    pub(crate) banner: Option<String>,
    /// Short actionable hint shown in the panel.
    pub(crate) hint: Option<String>,
    /// Fully qualified name of the field that owns the draft.
    pub(crate) active: Option<String>,
    /// Draft text of the focused field, committed on blur or Enter.
    pub(crate) draft: String,
}

impl FormsUiState {
    /// Drop everything tied to the previous document.
    fn reset_document(&mut self) {
        self.model = None;
        self.revision = None;
        self.tab = None;
        self.active = None;
        self.draft.clear();
    }
}

/// Why a form edit is refused, or `None` when filling is allowed.
///
/// The two inputs are the only gates: the tab's read-only state (an encrypted
/// document whose user permissions deny modification) and the `/Perms` mask
/// that carries `FILL_IN_FORM`. Read-only *fields* are refused separately by the
/// library, which returns `AcroFormError::ReadOnlyField`.
#[must_use]
pub(crate) fn form_edit_blocker(read_only: bool, fill_allowed: bool) -> Option<&'static str> {
    if read_only {
        return Some("This document is read-only, so its form cannot be filled.");
    }
    if !fill_allowed {
        return Some("The document permissions do not allow form filling.");
    }
    None
}

/// A field value rendered as the text a person expects to see.
#[must_use]
pub(crate) fn display_value(value: &FieldValue) -> String {
    match value {
        FieldValue::Empty => String::new(),
        FieldValue::Text(text) => text.clone(),
        FieldValue::Bool(true) => "On".to_owned(),
        FieldValue::Bool(false) => "Off".to_owned(),
        FieldValue::Choice(selected) => selected.join(", "),
        FieldValue::Number(number) => format!("{number}"),
    }
}

/// Map a page-space widget rectangle (PDF bottom-left origin) into the
/// top-left, y-down page frame the canvas overlays use.
#[must_use]
pub(crate) fn widget_page_rect(rect: FormRect, page_height_pt: f32) -> CanvasRect {
    CanvasRect::new(
        rect.left as f32,
        page_height_pt - rect.top as f32,
        rect.width() as f32,
        rect.height() as f32,
    )
}

impl PdfxiApp {
    /// The cached AcroForm model for the active tab, if the document has a form.
    #[must_use]
    pub fn forms_model(&self) -> Option<&AcroFormModel> {
        self.forms.model.as_ref()
    }

    /// Whether the document has at least one terminal AcroForm field.
    #[must_use]
    pub fn has_acroform(&self) -> bool {
        self.forms
            .model
            .as_ref()
            .is_some_and(|model| model.present && !model.is_empty())
    }

    /// Whether Fill & Sign can be offered for the active document.
    ///
    /// The capability must be enabled and the open document must carry a form:
    /// the tools-panel row is absent otherwise, so there is no control that can
    /// only report "not available".
    #[must_use]
    pub fn forms_available(&self) -> bool {
        self.capabilities.contains(Capability::Forms) && self.has_acroform()
    }

    /// Number of terminal fields in the cached model.
    #[must_use]
    pub fn form_field_count(&self) -> usize {
        self.forms.model.as_ref().map_or(0, AcroFormModel::len)
    }

    /// Every field's name and display value, in document order.
    ///
    /// This is the public read surface for tests and for the QA harness; the
    /// panel draws the same list.
    #[must_use]
    pub fn form_field_values(&self) -> Vec<(String, String)> {
        self.forms.model.as_ref().map_or_else(Vec::new, |model| {
            model
                .fields()
                .iter()
                .map(|field| (field.name.clone(), display_value(&field.value)))
                .collect()
        })
    }

    /// Total number of widgets (page rectangles) in the cached model.
    #[must_use]
    pub fn form_widget_count(&self) -> usize {
        self.forms.model.as_ref().map_or(0, |model| {
            model.fields().iter().map(|field| field.widgets.len()).sum()
        })
    }

    /// Whether the Fill & Sign panel window is open.
    #[must_use]
    pub fn forms_panel_open(&self) -> bool {
        self.forms.panel_open
    }

    /// The panel banner: a read error, or the XFA/JavaScript notice.
    #[must_use]
    pub fn forms_banner(&self) -> Option<&str> {
        self.forms.banner.as_deref()
    }

    /// The last actionable hint from a Fill & Sign action.
    #[must_use]
    pub fn forms_hint(&self) -> Option<&str> {
        self.forms.hint.as_deref()
    }

    /// The field whose draft is being edited, if any.
    #[must_use]
    pub fn active_form_field(&self) -> Option<&str> {
        self.forms.active.as_deref()
    }

    /// The uncommitted draft text of the focused field.
    #[must_use]
    pub fn form_draft(&self) -> Option<&str> {
        self.forms
            .active
            .as_ref()
            .map(|_| self.forms.draft.as_str())
    }

    /// Whether the active tab allows form changes.
    ///
    /// Read-only tabs and `/Perms` masks that deny `FILL_IN_FORM` both refuse;
    /// the panel shows one short sentence and the widgets are drawn without
    /// interaction instead of as dead controls.
    #[must_use]
    pub fn forms_editable(&self) -> bool {
        self.form_edit_blocker().is_none() && self.state.active_tab_id().is_some()
    }

    /// Why the active form cannot be edited, if it cannot.
    #[must_use]
    pub fn form_edit_blocker(&self) -> Option<&'static str> {
        let id = self.state.active_tab_id()?;
        let fill_allowed = self
            .sessions
            .get(&id)
            .and_then(pdfxi_document::DocumentSession::decryption_report)
            .is_none_or(|report| report.permissions.allows(Permission::FILL_FORMS));
        form_edit_blocker(self.read_only_tabs.contains(&id), fill_allowed)
    }

    /// Re-read the active document's AcroForm when the session revision moved.
    ///
    /// Called after open, tab switch, undo/redo and every form edit, so the
    /// widget overlay and the panel never show a value the document no longer
    /// has.
    pub fn refresh_forms(&mut self) {
        let Some(id) = self.state.active_tab_id() else {
            self.forms.reset_document();
            return;
        };
        if self.forms.tab != Some(id) {
            self.forms.reset_document();
            self.forms.tab = Some(id);
        }
        let Some(session) = self.sessions.get(&id) else {
            self.forms.reset_document();
            self.forms.tab = Some(id);
            return;
        };
        let revision = session.revision_count();
        if self.forms.revision == Some(revision) && self.forms.model.is_some() {
            return;
        }
        let read = read_acroform(session.document());
        self.forms.revision = Some(revision);
        match read {
            Ok(model) => {
                self.forms.banner = form_notice(&model);
                self.forms.model = Some(model);
            }
            Err(error) => {
                self.forms.banner = Some(error.to_string());
                self.forms.model = None;
            }
        }
        if !self.has_acroform() {
            self.forms.active = None;
            self.forms.draft.clear();
        }
    }

    /// Open the Fill & Sign tool: the field panel plus live page widgets.
    pub(crate) fn open_fill_and_sign(&mut self) {
        self.refresh_forms();
        if self.state.active_tab().is_none() {
            self.forms.hint = Some("Open a document with a form first.".to_owned());
            self.status = "Open a document before filling a form".to_owned();
            return;
        }
        if !self.capabilities.contains(Capability::Forms) {
            self.forms.hint = Some("Form filling is not enabled in this build.".to_owned());
            self.status = "Form filling is not enabled".to_owned();
            return;
        }
        self.forms.panel_open = true;
        match self.form_edit_blocker() {
            Some(blocker) => {
                self.forms.hint = Some(blocker.to_owned());
                self.status = blocker.to_owned();
                return;
            }
            None => self.forms.hint = None,
        }
        if !self.has_acroform() {
            self.forms.hint = Some("This document has no form fields to fill.".to_owned());
            self.status = "This document has no form fields".to_owned();
            return;
        }
        self.forms.hint = Some(
            "Click a field on the page to type; checkboxes toggle on click. Tab and Enter commit."
                .to_owned(),
        );
        self.status = "Fill & Sign: click a field on the page".to_owned();
    }

    /// Commit one text field value through a single undoable session edit.
    ///
    /// The library mutates a clone of the active document, exactly like the
    /// annotation path: a refusal (read-only field, wrong kind, unaddressable
    /// object) stays an app-level message instead of being forced through a
    /// session error variant that does not describe it.
    pub(crate) fn set_form_text(&mut self, name: &str, value: &str) {
        if let Some(blocker) = self.form_edit_blocker() {
            self.forms.hint = Some(blocker.to_owned());
            self.status = blocker.to_owned();
            return;
        }
        if !self.form_field_is_mutable(name, FormFieldKind::Text) {
            return;
        }
        let Some(id) = self.state.active_tab_id() else {
            return;
        };
        let Some(session) = self.sessions.get(&id) else {
            return;
        };
        let mut candidate = session.document().clone();
        if let Err(error) = set_text(&mut candidate, name, value) {
            self.forms.hint = Some(error.to_string());
            self.status = error.to_string();
            return;
        }
        let result = self
            .sessions
            .get_mut(&id)
            .ok_or(pdfxi_document::SessionError::NoPath)
            .and_then(|session| {
                session.edit(|document| {
                    *document = candidate;
                    Ok(())
                })
            });
        match result {
            Ok(()) => {
                self.after_session_edit(id);
                self.apply_cached_text(name, value);
                self.forms.active = None;
                self.forms.draft.clear();
                self.forms.hint = None;
                self.status = format!("Filled {name}");
            }
            Err(error) => {
                self.forms.hint = Some(error.to_string());
                self.status = error.to_string();
            }
        }
    }

    /// Toggle one checkbox through a single undoable session edit.
    pub(crate) fn toggle_form_checkbox(&mut self, name: &str) {
        if let Some(blocker) = self.form_edit_blocker() {
            self.forms.hint = Some(blocker.to_owned());
            self.status = blocker.to_owned();
            return;
        }
        if !self.form_field_is_mutable(name, FormFieldKind::Checkbox) {
            return;
        }
        let Some(id) = self.state.active_tab_id() else {
            return;
        };
        let next = !self
            .forms
            .model
            .as_ref()
            .and_then(|model| model.field(name))
            .is_some_and(|field| matches!(field.value, FieldValue::Bool(true)));
        let Some(session) = self.sessions.get(&id) else {
            return;
        };
        let mut candidate = session.document().clone();
        if let Err(error) = set_checkbox(&mut candidate, name, next) {
            self.forms.hint = Some(error.to_string());
            self.status = error.to_string();
            return;
        }
        let result = self
            .sessions
            .get_mut(&id)
            .ok_or(pdfxi_document::SessionError::NoPath)
            .and_then(|session| {
                session.edit(|document| {
                    *document = candidate;
                    Ok(())
                })
            });
        match result {
            Ok(()) => {
                self.after_session_edit(id);
                self.apply_cached_checkbox(name, next);
                self.forms.hint = None;
                self.status = format!("{} {name}", if next { "Checked" } else { "Cleared" });
            }
            Err(error) => {
                self.forms.hint = Some(error.to_string());
                self.status = error.to_string();
            }
        }
    }

    /// Whether `name` exists in the cached model with `kind` and is writable.
    ///
    /// A refusal writes a hint and returns `false`; the caller then skips the
    /// session edit so nothing is appended and the tab stays clean.
    fn form_field_is_mutable(&mut self, name: &str, kind: FormFieldKind) -> bool {
        let Some(field) = self
            .forms
            .model
            .as_ref()
            .and_then(|model| model.field(name))
            .cloned()
        else {
            self.forms.hint = Some(format!("{name} is not a field of this document."));
            self.status = format!("{name} is not a field of this document");
            return false;
        };
        if field.kind != kind {
            self.forms.hint = Some(format!(
                "{name} is a {} field, not a {} field.",
                field.kind.as_str(),
                kind.as_str()
            ));
            return false;
        }
        if field.read_only {
            self.forms.hint = Some(format!("{name} is read-only."));
            self.status = format!("{name} is read-only");
            return false;
        }
        true
    }

    /// Force the cached value to the value just committed.
    ///
    /// `read_acroform` documents that it returns the snapshot it was called
    /// with; the shell must not depend on a re-read seeing a staged write. The
    /// cached model is therefore updated with the value that was actually
    /// written, and the next refresh (save/reopen, undo, tab switch) replaces it
    /// from bytes.
    fn apply_cached_text(&mut self, name: &str, value: &str) {
        if let Some(model) = self.forms.model.as_mut()
            && let Some(field) = model.fields.iter_mut().find(|field| field.name == name)
        {
            field.value = FieldValue::Text(value.to_owned());
            for widget in &mut field.widgets {
                widget.has_appearance = true;
            }
        }
    }

    fn apply_cached_checkbox(&mut self, name: &str, checked: bool) {
        if let Some(model) = self.forms.model.as_mut()
            && let Some(field) = model.fields.iter_mut().find(|field| field.name == name)
        {
            field.value = FieldValue::Bool(checked);
            for widget in &mut field.widgets {
                widget.has_appearance = true;
            }
        }
    }

    /// The Fill & Sign panel: field list, values and the edit state.
    pub(crate) fn forms_panel_ui(&mut self, ctx: &egui::Context) {
        if !self.forms.panel_open {
            return;
        }
        let palette = Palette::for_mode(self.theme);
        let mut open = true;
        // Default to the lower-left of the workspace: the first fields of a
        // page are usually near its top-left corner, so the panel must not sit
        // on top of the widgets it describes. The window stays movable.
        let screen = ctx.content_rect();
        let default_pos = egui::pos2(screen.left() + 292.0, screen.bottom() - 396.0);
        egui::Window::new("Fill & Sign")
            .open(&mut open)
            .resizable(true)
            .default_pos(default_pos)
            .default_width(268.0)
            .show(ctx, |ui| {
                ui.set_max_width(320.0);
                if let Some(banner) = self.forms.banner.clone() {
                    ui.colored_label(ui.visuals().warn_fg_color, banner);
                }
                if let Some(hint) = self.forms.hint.clone() {
                    ui.label(
                        egui::RichText::new(hint)
                            .size(11.0)
                            .color(palette.text_muted),
                    );
                }
                if self.state.active_tab().is_none() {
                    ui.label(egui::RichText::new("Open a document with a form.").weak());
                    return;
                }
                if !self.has_acroform() {
                    ui.label(
                        egui::RichText::new("No form fields in this document.")
                            .color(palette.text_muted),
                    );
                    return;
                }
                ui.label(
                    egui::RichText::new(format!(
                        "{} field(s), {} on this page",
                        self.form_field_count(),
                        self.form_widget_count()
                    ))
                    .size(10.5)
                    .color(palette.text_muted),
                );
                ui.separator();
                let values = self.form_field_values();
                let kinds: Vec<(String, String)> = self
                    .forms
                    .model
                    .as_ref()
                    .map(|model| {
                        model
                            .fields()
                            .iter()
                            .map(|field| (field.name.clone(), field.kind.as_str().to_owned()))
                            .collect()
                    })
                    .unwrap_or_default();
                for ((name, value), (_, kind)) in values.iter().zip(kinds.iter()) {
                    ui.horizontal(|ui| {
                        ui.label(egui::RichText::new(name).size(11.5));
                        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                            ui.label(
                                egui::RichText::new(kind)
                                    .size(10.0)
                                    .color(palette.text_muted),
                            );
                        });
                    });
                    ui.label(
                        egui::RichText::new(if value.is_empty() {
                            "—"
                        } else {
                            value.as_str()
                        })
                        .size(11.0)
                        .color(palette.text),
                    );
                    ui.add_space(2.0);
                }
                ui.separator();
                ui.label(
                    egui::RichText::new(
                        "Values are written with appearances and saved with the document.",
                    )
                    .size(10.0)
                    .color(palette.text_muted),
                );
            });
        if !open {
            self.forms.panel_open = false;
        }
    }

    /// Draw every visible form widget over the page and handle its input.
    ///
    /// The page-to-screen mapping is the same as the find, selection and
    /// annotation overlays: a PDF rectangle is flipped into the page's
    /// top-left frame and mapped forward through
    /// [`CanvasLayout::page_rect_to_canvas`], so rotation and zoom agree with
    /// the raster underneath.
    pub(crate) fn form_widgets_ui(
        &mut self,
        ui: &mut egui::Ui,
        layout: &CanvasLayout,
        origin: egui::Pos2,
        pad_x: f32,
    ) {
        let Some(model) = self.forms.model.clone() else {
            return;
        };
        if !model.present || model.is_empty() {
            return;
        }
        let palette = Palette::for_mode(self.theme);
        let editable = self.forms_editable();
        let screen = ui.clip_rect();
        for field in model.fields() {
            for widget in &field.widgets {
                let Some(page) = widget.page else {
                    continue;
                };
                let Some(page_size) = self.page_sizes.get(page) else {
                    continue;
                };
                let local = widget_page_rect(widget.rect, page_size.height_pt);
                let Some(mapped) = layout.page_rect_to_canvas(page, local) else {
                    continue;
                };
                let rect = egui::Rect::from_min_size(
                    egui::pos2(
                        origin.x + mapped.x - self.scroll_x + pad_x,
                        origin.y + mapped.y - self.scroll_y,
                    ),
                    egui::vec2(mapped.width.max(2.0), mapped.height.max(2.0)),
                );
                if !rect.intersects(screen) {
                    continue;
                }
                let id = ui.make_persistent_id(("pdfxi-form-widget", &field.name, mapped.x as i32));
                match field.kind {
                    FormFieldKind::Text => {
                        self.form_text_widget_ui(ui, &palette, rect, id, field, editable);
                    }
                    FormFieldKind::Checkbox => {
                        self.form_checkbox_widget_ui(ui, &palette, rect, id, field, editable);
                    }
                    FormFieldKind::Choice
                    | FormFieldKind::Radio
                    | FormFieldKind::Button
                    | FormFieldKind::Signature => {
                        draw_field_box(&palette, ui, rect, false);
                        let label = display_value(&field.value);
                        if !label.is_empty() {
                            let font = egui::FontId::proportional(field_font_size(rect));
                            ui.painter().text(
                                rect.left_center() + egui::vec2(4.0, 0.0),
                                egui::Align2::LEFT_CENTER,
                                label,
                                font,
                                FIELD_INK_MUTED,
                            );
                        }
                    }
                }
            }
        }
    }

    fn form_text_widget_ui(
        &mut self,
        ui: &mut egui::Ui,
        palette: &Palette,
        rect: egui::Rect,
        id: egui::Id,
        field: &pdfxi_forms::FormField,
        editable: bool,
    ) {
        let focused = self.forms.active.as_deref() == Some(field.name.as_str());
        if focused && editable {
            let font = egui::FontId::proportional(field_font_size(rect));
            let response = ui.put(
                rect,
                egui::TextEdit::singleline(&mut self.forms.draft)
                    .font(font)
                    .text_color(FIELD_INK)
                    .margin(egui::Margin::symmetric(2, 1)),
            );
            if response.lost_focus() {
                if ui.input(|input| input.key_pressed(egui::Key::Escape)) {
                    self.forms.active = None;
                    self.forms.draft.clear();
                } else {
                    let value = self.forms.draft.clone();
                    self.dispatch(
                        AppCommand::SetFormText {
                            name: field.name.clone(),
                            value,
                        },
                        Some(ui.ctx()),
                    );
                }
            }
            return;
        }
        draw_field_box(palette, ui, rect, focused);
        let value = display_value(&field.value);
        ui.painter().text(
            rect.left_center() + egui::vec2(4.0, 0.0),
            egui::Align2::LEFT_CENTER,
            if value.is_empty() {
                " "
            } else {
                value.as_str()
            },
            egui::FontId::proportional(field_font_size(rect)),
            if editable { FIELD_INK } else { FIELD_INK_MUTED },
        );
        if !editable {
            return;
        }
        let response = ui.interact(rect, id, egui::Sense::click());
        if response.clicked() {
            self.forms.active = Some(field.name.clone());
            self.forms.draft = value;
            ui.ctx().memory_mut(|memory| memory.request_focus(id));
        }
    }

    fn form_checkbox_widget_ui(
        &mut self,
        ui: &mut egui::Ui,
        palette: &Palette,
        rect: egui::Rect,
        id: egui::Id,
        field: &pdfxi_forms::FormField,
        editable: bool,
    ) {
        let checked = matches!(field.value, FieldValue::Bool(true));
        let response = ui.interact(
            rect,
            id,
            if editable {
                egui::Sense::click()
            } else {
                egui::Sense::hover()
            },
        );
        let painter = ui.painter();
        painter.rect_filled(rect, 1.0, palette.paper);
        let stroke = if response.hovered() && editable {
            egui::Stroke::new(1.5_f32, palette.accent)
        } else {
            egui::Stroke::new(1.0_f32, palette.border)
        };
        painter.rect_stroke(rect, 1.0, stroke, egui::StrokeKind::Inside);
        if checked {
            // A vector check mark, not a filled block: it reads as checked in
            // both themes and does not look like a debug overlay.
            let inset = (rect.width().min(rect.height()) * 0.2).max(2.0);
            let left = rect.min + egui::vec2(inset, inset * 1.6);
            let corner = egui::pos2(
                rect.left() + rect.width() * 0.42,
                rect.bottom() - inset * 1.3,
            );
            let right = egui::pos2(rect.right() - inset * 0.8, rect.top() + inset * 1.1);
            let tick = egui::Stroke::new((rect.height() * 0.1).clamp(1.5, 3.0), FIELD_INK);
            painter.line_segment([left, corner], tick);
            painter.line_segment([corner, right], tick);
        }
        if response.clicked() {
            self.dispatch(
                AppCommand::ToggleFormCheckbox {
                    name: field.name.clone(),
                },
                Some(ui.ctx()),
            );
        }
    }
}

/// Ink used for widget text drawn on the page.
///
/// The page paper is near-white in every theme, so page-space text must not use
/// the theme's text colour: in dark mode that is near-white and would vanish.
const FIELD_INK: egui::Color32 = egui::Color32::from_rgb(0x1f, 0x22, 0x26);
/// Ink used for a widget value the user cannot change.
const FIELD_INK_MUTED: egui::Color32 = egui::Color32::from_rgb(0x6a, 0x6f, 0x76);

/// Banner text for a form that needs a caveat rather than an error.
fn form_notice(model: &AcroFormModel) -> Option<String> {
    if model.contains_xfa {
        return Some(
            "This form also carries XFA content. It is not rendered or executed; the AcroForm \
             fields below are the ones that can be filled."
                .to_owned(),
        );
    }
    if model.has_javascript {
        return Some(
            "This form uses JavaScript actions. They are not executed; values are written \
             directly."
                .to_owned(),
        );
    }
    None
}

/// Font size for a widget's value text, derived from its height.
fn field_font_size(rect: egui::Rect) -> f32 {
    (rect.height() * 0.62).clamp(8.0, 18.0)
}

/// Paint the paper box behind a widget rectangle.
fn draw_field_box(palette: &Palette, ui: &egui::Ui, rect: egui::Rect, focused: bool) {
    let painter = ui.painter();
    painter.rect_filled(
        rect,
        1.5,
        egui::Color32::from_rgba_unmultiplied(255, 255, 255, 220),
    );
    let stroke = if focused {
        egui::Stroke::new(1.5_f32, palette.accent)
    } else {
        egui::Stroke::new(1.0_f32, palette.border)
    };
    painter.rect_stroke(rect, 1.5, stroke, egui::StrokeKind::Inside);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn form_edit_gate_refuses_read_only_and_missing_permission() {
        assert_eq!(form_edit_blocker(false, true), None);
        assert!(form_edit_blocker(true, true).is_some_and(|message| message.contains("read-only")));
        assert!(
            form_edit_blocker(false, false).is_some_and(|message| message.contains("permissions"))
        );
        // Read-only wins: it is the state the user can see in the tab.
        assert!(
            form_edit_blocker(true, false).is_some_and(|message| message.contains("read-only"))
        );
    }

    #[test]
    fn field_values_display_as_text() {
        assert_eq!(display_value(&FieldValue::Empty), "");
        assert_eq!(
            display_value(&FieldValue::Text("filled".to_owned())),
            "filled"
        );
        assert_eq!(display_value(&FieldValue::Bool(true)), "On");
        assert_eq!(display_value(&FieldValue::Bool(false)), "Off");
        assert_eq!(
            display_value(&FieldValue::Choice(vec![
                "one".to_owned(),
                "two".to_owned()
            ])),
            "one, two"
        );
    }

    #[test]
    fn widget_rect_flips_the_page_axis() {
        let rect = FormRect::new(72.0, 700.0, 272.0, 720.0);
        let local = widget_page_rect(rect, 792.0);
        assert_eq!(local.x, 72.0);
        assert_eq!(local.y, 72.0);
        assert_eq!(local.width, 200.0);
        assert_eq!(local.height, 20.0);
    }

    #[test]
    fn notice_names_xfa_and_javascript_without_claiming_execution() {
        let mut model = AcroFormModel {
            present: true,
            contains_xfa: true,
            ..AcroFormModel::default()
        };
        assert!(
            form_notice(&model).is_some_and(|notice| notice.contains("not rendered or executed"))
        );
        model.contains_xfa = false;
        model.has_javascript = true;
        assert!(form_notice(&model).is_some_and(|notice| notice.contains("not executed")));
        model.has_javascript = false;
        assert_eq!(form_notice(&model), None);
    }
}

#[cfg(all(test, feature = "pdfium"))]
mod integration_tests {
    //! Real fixture, real session, real PDFium.

    use super::*;
    use pdfxi_render::{CancellationToken, PageIndex, PdfiumRenderer, Renderer};
    use std::path::PathBuf;

    /// The committed self-made AcroForm fixture: one page with a text, a
    /// checkbox and a choice field, all with real widget rectangles.
    fn fixture() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/realworld/pdfxi-forms-selfmade.pdf")
    }

    fn output_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target/lanes/app2/t0243-out")
    }

    fn open_forms() -> PdfxiApp {
        let mut app = PdfxiApp::new();
        assert!(
            matches!(
                app.open_document(&fixture()),
                crate::OpenOutcome::Opened { .. }
            ),
            "the forms fixture must open"
        );
        app
    }

    fn value(app: &PdfxiApp, name: &str) -> String {
        app.form_field_values()
            .into_iter()
            .find(|(field, _)| field == name)
            .map(|(_, value)| value)
            .unwrap_or_default()
    }

    #[test]
    fn fills_text_and_checkbox_then_undo_and_redo_restore_values() {
        let mut app = open_forms();

        // 1. The fixture is enumerated from real bytes.
        assert!(app.has_acroform(), "the fixture carries an /AcroForm");
        assert_eq!(app.form_field_count(), 3);
        assert_eq!(app.form_widget_count(), 3);
        assert_eq!(value(&app, "text-field"), "typed value");
        assert_eq!(value(&app, "checkbox-field"), "On");
        assert!(
            app.tools_panel_rows()
                .iter()
                .any(|row| row.label == "Fill & Sign"),
            "the Fill & Sign row must appear for a document with a form"
        );

        // 2. The command opens the real tool, not a status string.
        app.dispatch(AppCommand::FillAndSign, None);
        assert!(app.forms_panel_open());
        assert!(app.forms_editable(), "the fixture has no fill restriction");
        assert_eq!(app.forms_banner(), None);

        // 3. A text commit is one undoable session edit that marks the tab dirty.
        app.dispatch(
            AppCommand::SetFormText {
                name: "text-field".to_owned(),
                value: "Filled by the viewer".to_owned(),
            },
            None,
        );
        assert_eq!(value(&app, "text-field"), "Filled by the viewer");
        assert!(app.state().active_tab().is_some_and(|tab| tab.is_dirty()));
        assert!(app.can_undo());

        // 4. The checkbox toggles from its real `/V /Yes` state.
        app.dispatch(
            AppCommand::ToggleFormCheckbox {
                name: "checkbox-field".to_owned(),
            },
            None,
        );
        assert_eq!(value(&app, "checkbox-field"), "Off");

        // 5. Undo restores the checkbox, then the text; redo reapplies both.
        app.dispatch(AppCommand::Undo, None);
        assert_eq!(value(&app, "checkbox-field"), "On");
        assert_eq!(value(&app, "text-field"), "Filled by the viewer");
        app.dispatch(AppCommand::Undo, None);
        assert_eq!(value(&app, "text-field"), "typed value");
        assert!(app.can_redo());
        app.dispatch(AppCommand::Redo, None);
        assert_eq!(value(&app, "text-field"), "Filled by the viewer");
        app.dispatch(AppCommand::Redo, None);
        assert_eq!(value(&app, "checkbox-field"), "Off");
    }

    #[test]
    fn read_only_render_cannot_be_edited_even_from_the_command() {
        // The gate is a unit-tested pure function; this proves the command path
        // consults it: a viewer whose tab is read-only refuses and stays clean.
        let mut app = open_forms();
        let id = app.state().active_tab_id().expect("active tab");
        app.read_only_tabs.insert(id);
        app.dispatch(
            AppCommand::SetFormText {
                name: "text-field".to_owned(),
                value: "must not land".to_owned(),
            },
            None,
        );
        app.dispatch(
            AppCommand::ToggleFormCheckbox {
                name: "checkbox-field".to_owned(),
            },
            None,
        );
        assert_eq!(value(&app, "text-field"), "typed value");
        assert_eq!(value(&app, "checkbox-field"), "On");
        assert!(
            app.forms_hint()
                .is_some_and(|hint| hint.contains("read-only")),
            "a refusal needs a readable hint, hint was {:?}",
            app.forms_hint()
        );
        assert!(
            !app.state().active_tab().is_some_and(|tab| tab.is_dirty()),
            "a refused edit must not dirty the tab"
        );
    }

    /// Count non-white pixels inside a PDF rectangle of a rendered page.
    fn ink_in_pdf_rect(
        raster: &pdfxi_render::RenderedPage,
        rect: FormRect,
        scale: f32,
        page_height_pt: f32,
    ) -> usize {
        let width = raster.width() as usize;
        let height = raster.height() as usize;
        let pixels = raster.pixels();
        let x0 = (rect.left as f32 * scale).floor().max(0.0) as usize;
        let x1 = ((rect.right as f32 * scale).ceil() as usize).min(width);
        let y0 = ((page_height_pt - rect.top as f32) * scale)
            .floor()
            .max(0.0) as usize;
        let y1 = (((page_height_pt - rect.bottom as f32) * scale).ceil() as usize).min(height);
        let mut ink = 0usize;
        for y in y0..y1 {
            for x in x0..x1 {
                let index = (y * width + x) * 4;
                if let Some(pixel) = pixels.get(index..index + 4)
                    && (pixel[0] < 235 || pixel[1] < 235 || pixel[2] < 235)
                {
                    ink += 1;
                }
            }
        }
        ink
    }

    #[test]
    fn saved_values_persist_and_the_page_renders_the_filled_text() {
        let mut app = open_forms();
        app.dispatch(AppCommand::FillAndSign, None);
        app.dispatch(
            AppCommand::SetFormText {
                name: "text-field".to_owned(),
                value: "Reviewed 2026-11-20".to_owned(),
            },
            None,
        );
        // Off then On: two edits prove the toggle both ways and leave a checked
        // box with a regenerated appearance for the capture.
        app.dispatch(
            AppCommand::ToggleFormCheckbox {
                name: "checkbox-field".to_owned(),
            },
            None,
        );
        app.dispatch(
            AppCommand::ToggleFormCheckbox {
                name: "checkbox-field".to_owned(),
            },
            None,
        );
        assert_eq!(value(&app, "checkbox-field"), "On");

        let dir = output_dir();
        std::fs::create_dir_all(&dir).expect("create the output directory");
        let target = dir.join("filled.pdf");
        app.save_active_as(&target).expect("save the filled form");
        assert!(!app.state().active_tab().is_some_and(|tab| tab.is_dirty()));
        // The capture script opens this name; it is the same saved bytes.
        std::fs::copy(&target, dir.join("filled-form.pdf")).expect("copy the capture artifact");

        // A fresh app and a fresh session read the values back from the file.
        let mut viewer = PdfxiApp::new();
        assert!(matches!(
            viewer.open_document(&target),
            crate::OpenOutcome::Opened { .. }
        ));
        assert_eq!(viewer.form_field_count(), 3);
        assert_eq!(value(&viewer, "text-field"), "Reviewed 2026-11-20");
        assert_eq!(value(&viewer, "checkbox-field"), "On");

        // Independent proof: PDFium renders the page and the widget rectangle
        // carries ink for the appearance text, which a `/V`-only write cannot do.
        let bytes = std::fs::read(&target).expect("read the saved file");
        let renderer = PdfiumRenderer::from_bytes(bytes).expect("open the saved file in PDFium");
        let token = CancellationToken::new();
        let scale = 2.0_f32;
        let raster = renderer
            .render_page(PageIndex::new(0), scale, &token, &mut |_| {})
            .expect("render the saved page");
        let text_rect = FormRect::new(72.0, 700.0, 272.0, 720.0);
        let ink = ink_in_pdf_rect(&raster, text_rect, scale, 792.0);
        assert!(
            ink > 40,
            "the filled text appearance must paint inside {text_rect:?}; found {ink} ink pixels"
        );
    }
}
